mapper.select:
SELECT summary_id
FROM summary
WHERE user_id = #{userId}
  AND counseling_result_id = #{counselingResultId}
ORDER BY summary_id DESC
    LIMIT 1

mapper.update:
UPDATE summary
SET status = #{status}
WHERE summary_id = #{summaryId}

mapper.select:
SELECT is_bookmarked
FROM summary
WHERE summary_id = #{summaryId}

mapper.update:
UPDATE summary
SET is_bookmarked = #{isBookmarked}
WHERE summary_id = #{summaryId}
